INSERT INTO trivia_questions (question, option_a, option_b, option_c, option_d, correct_answer, explanation, category, difficulty) VALUES
('What does THC stand for?', 'Tetrahydrocannabinol', 'Tetrahydrocarbon', 'Trichome Harvest Compound', 'Total Hemp Content', 'A', 'THC (tetrahydrocannabinol) is the primary psychoactive compound in cannabis.', 'cannabis', 'Easy'),
('What does CBD stand for?', 'Cannabidiol', 'Cannabis-Based Derivative', 'Concentrated Botanical Drug', 'Cannabinoid Dosage Base', 'A', 'CBD (cannabidiol) is a non-psychoactive cannabinoid known for potential therapeutic benefits.', 'cannabis', 'Easy'),
('Which part of the cannabis plant contains the most cannabinoids?', 'The stems', 'The flower (bud)', 'The roots', 'The fan leaves', 'B', 'The flower or bud contains the highest concentration of cannabinoids and terpenes, produced in the trichomes.', 'cannabis', 'Easy'),
('What are trichomes?', 'The roots of the plant', 'Tiny crystal-like resin glands on the flower', 'The seeds', 'A type of fertilizer', 'B', 'Trichomes are the tiny, sparkly, mushroom-shaped resin glands that produce cannabinoids and terpenes.', 'cannabis', 'Easy'),
('What is a pre-roll?', 'A rolled cannabis joint sold ready to smoke', 'A type of edible', 'A vape cartridge', 'A topical cream', 'A', 'Pre-rolls are joints rolled by the producer and sold ready to smoke. Available as singles or multi-packs.', 'cannabis', 'Easy'),
('What is the minimum age to purchase cannabis in New York?', '18', '19', '21', '25', 'C', 'You must be 21 or older to purchase adult-use cannabis in New York State.', 'cannabis', 'Easy'),
('What does "indica" traditionally suggest about a strain''s effects?', 'Energizing and uplifting', 'Relaxing and sedating', 'No effects at all', 'Only affects appetite', 'B', 'Indica strains are traditionally associated with relaxing, body-heavy effects. Think "in-da-couch."', 'cannabis', 'Easy'),
('What does "sativa" traditionally suggest about a strain''s effects?', 'Sedating and sleepy', 'Energizing and uplifting', 'No psychoactive effects', 'Only medical use', 'B', 'Sativa strains are traditionally associated with energizing, cerebral, uplifting effects.', 'cannabis', 'Easy'),
('What is a hybrid strain?', 'A strain crossed from indica and sativa genetics', 'A synthetic cannabis product', 'A strain with no THC', 'A strain grown only indoors', 'A', 'Hybrids are bred from both indica and sativa parent strains, offering a mix of effects.', 'cannabis', 'Easy'),
('What is a topical cannabis product?', 'A cream or balm applied to the skin', 'A type of edible', 'A vape pen', 'A type of flower', 'A', 'Topicals are cannabis-infused lotions, balms, or patches applied directly to the skin for localized relief.', 'cannabis', 'Easy'),
('Do topical cannabis products typically get you high?', 'Yes, always', 'No, they generally don''t produce psychoactive effects', 'Only if applied to the face', 'Only in large amounts', 'B', 'Most topicals don''t enter the bloodstream, so they provide localized relief without psychoactive effects.', 'cannabis', 'Easy'),
('What is a dab?', 'A small dose of cannabis concentrate vaporized on a hot surface', 'A type of edible gummy', 'A rolling paper brand', 'A strain of flower', 'A', 'Dabbing involves vaporizing a small amount of cannabis concentrate on a heated surface (nail or banger) and inhaling.', 'cannabis', 'Easy'),
('What is live resin?', 'A concentrate made from fresh-frozen cannabis to preserve terpenes', 'Dried flower that has been pressed', 'An edible made with real fruit', 'A topical cream', 'A', 'Live resin is made from cannabis that was flash-frozen immediately after harvest, preserving the full terpene profile.', 'cannabis', 'Easy'),
('What is the "entourage effect"?', 'When you bring friends to the dispensary', 'The idea that cannabinoids and terpenes work better together than alone', 'A type of high from edibles', 'A marketing term with no science behind it', 'B', 'The entourage effect suggests that the full spectrum of cannabis compounds (cannabinoids, terpenes, flavonoids) work synergistically.', 'cannabis', 'Easy'),
('What is an eighth?', '1/8 of a gram', '1/8 of an ounce (3.5 grams)', '8 grams', '1/8 of a pound', 'B', 'An eighth is 3.5 grams, one of the most common quantities for purchasing flower.', 'cannabis', 'Easy'),
('How many grams are in an ounce of cannabis?', '14', '21', '28', '32', 'C', 'One ounce equals 28 grams. An eighth (3.5g) x 8 = 28g.', 'cannabis', 'Easy'),
('What is a dispensary?', 'A licensed retail store that sells cannabis products', 'A cannabis farm', 'A testing laboratory', 'A doctor''s office', 'A', 'A dispensary is a state-licensed retail location authorized to sell cannabis products to consumers.', 'cannabis', 'Easy'),
('What does "full-spectrum" mean on a cannabis product?', 'It contains only THC', 'It contains the full range of cannabinoids, terpenes, and other plant compounds', 'It''s the strongest product available', 'It only comes in edible form', 'B', 'Full-spectrum products retain the plant''s full profile of cannabinoids, terpenes, and flavonoids.', 'cannabis', 'Easy'),
('What is a cannabis isolate?', 'A product containing only one isolated cannabinoid (usually THC or CBD)', 'A full-spectrum product', 'A type of flower', 'An outdoor-grown strain', 'A', 'Isolates are refined to contain a single cannabinoid (like pure CBD or pure THC) with everything else removed.', 'cannabis', 'Easy'),
('What is a cartridge (cart)?', 'A pre-filled container of cannabis oil that attaches to a battery for vaping', 'A type of rolling paper', 'A container for storing flower', 'A measuring tool', 'A', 'Carts are pre-filled with cannabis oil and screw onto a compatible battery pen for vaping.', 'cannabis', 'Easy'),
('What is decarboxylation?', 'A drying technique', 'The process of applying heat to activate cannabinoids', 'A way to remove THC', 'A packaging method', 'B', 'Raw cannabis contains THCa, which must be heated (decarbed) to convert into active THC. This happens when you smoke, vape, or bake with cannabis.', 'cannabis', 'Easy'),
('Can you return cannabis products after purchase in New York?', 'Yes, within 30 days', 'Yes, if unopened', 'No, all sales are final', 'Only edibles can be returned', 'C', 'Due to regulatory requirements, all cannabis sales are final. Products cannot be returned once purchased.', 'cannabis', 'Easy'),
('What is a budtender?', 'A cannabis retail associate who helps customers', 'A person who grows cannabis', 'A cannabis inspector', 'A brand ambassador', 'A', 'A budtender is the customer-facing staff member at a dispensary who helps customers find the right products.', 'cannabis', 'Easy'),
('What color are mature trichomes ready for harvest?', 'Clear/transparent', 'Milky white to amber', 'Bright green', 'Dark brown', 'B', 'Milky/cloudy trichomes indicate peak THC. Amber trichomes suggest some THC has converted to CBN (more sedating).', 'cannabis', 'Easy'),
('What is kief?', 'The loose trichomes that collect at the bottom of a grinder', 'A type of edible', 'A cannabis strain', 'A rolling technique', 'A', 'Kief is the collection of loose trichomes that fall off flower, usually accumulating in the bottom chamber of a grinder.', 'cannabis', 'Easy'),
('What does "sun-grown" mean?', 'Cannabis grown outdoors using natural sunlight', 'Cannabis grown under LED lights', 'Cannabis dried in the sun', 'A brand name', 'A', 'Sun-grown cannabis is cultivated outdoors using natural sunlight, often considered more sustainable and flavorful.', 'cannabis', 'Easy'),
('What is a strain?', 'A specific variety or cultivar of cannabis with distinct characteristics', 'A measurement of potency', 'A type of extraction', 'A quality grade', 'A', 'A strain (or cultivar) is a specific genetic variety of cannabis with its own unique appearance, aroma, flavor, and effects.', 'cannabis', 'Easy'),
('Which cannabinoid is known for potential sleep-promoting properties?', 'THC', 'CBD', 'CBN', 'CBG', 'C', 'CBN (cannabinol) is often associated with sedating effects and is found in aged cannabis as THC degrades over time.', 'cannabis', 'Easy'),
('What does RSO stand for?', 'Rick Simpson Oil', 'Refined Strain Output', 'Regular Standard Oil', 'Resin Solvent Oxide', 'A', 'RSO (Rick Simpson Oil) is a full-spectrum, highly concentrated cannabis extract typically taken orally.', 'cannabis', 'Easy'),
('What is the purpose of a grinder?', 'To break down flower into smaller, even pieces for smoking', 'To extract concentrates', 'To test potency', 'To package products', 'A', 'A grinder breaks flower into a consistent, even texture for better airflow and more even burning in joints or bowls.', 'cannabis', 'Easy');
INSERT INTO trivia_questions (question, option_a, option_b, option_c, option_d, correct_answer, explanation, category, difficulty) VALUES
('What terpene gives cannabis a citrusy, lemon scent?', 'Myrcene', 'Limonene', 'Pinene', 'Linalool', 'B', 'Limonene is responsible for citrus aromas. Also found in lemon rinds and orange peels.', 'cannabis', 'Medium'),
('What terpene is most commonly found in cannabis and has an earthy, musky aroma?', 'Limonene', 'Pinene', 'Myrcene', 'Caryophyllene', 'C', 'Myrcene is the most abundant terpene in cannabis. It has an earthy, herbal scent and is also found in mangoes and hops.', 'cannabis', 'Medium'),
('Which terpene smells like pine trees?', 'Myrcene', 'Linalool', 'Alpha-Pinene', 'Terpinolene', 'C', 'Alpha-Pinene has a sharp pine scent and is also found in pine needles and rosemary. It may support alertness.', 'cannabis', 'Medium'),
('Which terpene has a floral, lavender scent and is associated with calming effects?', 'Caryophyllene', 'Linalool', 'Humulene', 'Ocimene', 'B', 'Linalool has a floral, lavender aroma and is associated with relaxation and stress relief.', 'cannabis', 'Medium'),
('What makes beta-caryophyllene unique among terpenes?', 'It has no smell', 'It can bind to CB2 receptors like a cannabinoid', 'It only exists in indica strains', 'It evaporates instantly', 'B', 'Beta-caryophyllene is the only terpene known to directly activate CB2 cannabinoid receptors, giving it anti-inflammatory properties.', 'cannabis', 'Medium'),
('What is the difference between THC and THCa?', 'They are the same thing', 'THCa is the raw, non-psychoactive form that converts to THC when heated', 'THC is weaker than THCa', 'THCa only exists in edibles', 'B', 'THCa (tetrahydrocannabinolic acid) is the raw precursor. It needs heat (decarboxylation) to become psychoactive THC.', 'cannabis', 'Medium'),
('What is CBG?', 'A synthetic cannabinoid', 'The "mother cannabinoid" from which other cannabinoids are derived', 'A type of terpene', 'A concentrate consistency', 'B', 'CBG (cannabigerol) is called the mother cannabinoid because CBGa is the precursor molecule that converts into THCa, CBDa, and CBCa.', 'cannabis', 'Medium'),
('What is Delta-8 THC?', 'A stronger form of regular THC', 'A naturally occurring minor cannabinoid similar to Delta-9 THC but with milder effects', 'A synthetic chemical', 'Another name for CBD', 'B', 'Delta-8 THC occurs naturally in small amounts. It has similar but milder psychoactive effects compared to Delta-9 THC.', 'cannabis', 'Medium'),
('What is "curing" in cannabis production?', 'The process of slowly drying harvested cannabis in controlled conditions to improve flavor and smoothness', 'Adding chemicals to preserve the flower', 'Removing seeds from the plant', 'A marketing technique', 'A', 'Curing involves storing dried cannabis in sealed containers, periodically burping them. This breaks down chlorophyll and develops the terpene profile.', 'cannabis', 'Medium'),
('What does COA stand for in cannabis?', 'Certificate of Analysis', 'Certificate of Authenticity', 'Cannabis Origin Assessment', 'Compliance Operations Audit', 'A', 'A COA (Certificate of Analysis) is the lab test report showing potency, terpene profile, and contaminant screening results.', 'cannabis', 'Medium'),
('What is "living soil" cultivation?', 'Growing in soil with a thriving ecosystem of microorganisms', 'Growing in sand', 'Hydroponic growing', 'Growing with artificial nutrients only', 'A', 'Living soil relies on a natural ecosystem of beneficial microbes, fungi, and worms to feed the plant, producing what many consider more flavorful cannabis.', 'cannabis', 'Medium'),
('What is the difference between rosin and resin?', 'They are the same thing', 'Rosin is solventless (heat and pressure); resin uses solvents', 'Resin is better quality', 'Rosin is only from outdoor plants', 'B', 'Rosin is extracted using only heat and pressure (solventless). Resin typically involves solvent-based extraction methods.', 'cannabis', 'Medium'),
('What is a "nano" edible?', 'A very small edible', 'An edible using nano-emulsion technology for faster onset', 'An edible with no THC', 'An edible shaped like a molecule', 'B', 'Nano-emulsion breaks cannabinoids into tiny particles that absorb faster. Onset can be 15-30 minutes instead of 1-2 hours.', 'cannabis', 'Medium'),
('Why do some cannabis products list both THC and THCa percentages?', 'They are different measurements of the same thing', 'THCa is the raw form; the total THC after heating is calculated from both', 'It''s a labeling error', 'Only one matters', 'B', 'Labels show THCa (raw) and Delta-9 THC (already active). Total THC = (THCa x 0.877) + Delta-9 THC.', 'cannabis', 'Medium'),
('What is "budder" (or "badder")?', 'A cannabis-infused butter for cooking', 'A concentrate consistency that is soft, creamy, and easy to scoop', 'A type of flower', 'A brand name', 'B', 'Budder/badder is a concentrate consistency whipped during processing to create a smooth, butter-like texture.', 'cannabis', 'Medium'),
('What is a "diamond" in cannabis concentrates?', 'A crystalline form of pure THCa', 'A high-end strain of flower', 'A type of vape battery', 'A grading system', 'A', 'Diamonds are crystalline structures of nearly pure THCa (up to 99%). They form during a slow crystallization process.', 'cannabis', 'Medium'),
('What is a 1:1 ratio product?', 'A product with equal amounts of THC and CBD', 'A product that is half flower half concentrate', 'A dosing method', 'A type of strain', 'A', '1:1 products contain equal parts THC and CBD. The CBD helps moderate the THC effects, making it a good option for beginners or those sensitive to THC.', 'cannabis', 'Medium'),
('What is "trim run" concentrate?', 'Concentrate made from sugar leaves and trim rather than top buds', 'The first extraction of the season', 'A running technique for farmers', 'A premium concentrate grade', 'A', 'Trim run uses the sugar leaves and smaller pieces trimmed from buds. It''s typically less potent and less flavorful than nug run (made from whole buds).', 'cannabis', 'Medium'),
('What does "nug run" mean?', 'A concentrate made from whole cannabis buds rather than trim', 'Running with a bag of flower', 'A strain name', 'A delivery method', 'A', 'Nug run concentrates are made from whole, top-quality buds, resulting in higher potency and better flavor than trim run.', 'cannabis', 'Medium'),
('A customer asks for something to help with muscle soreness but doesn''t want to feel high. What do you recommend?', 'A high-THC vape cart', 'A cannabis topical cream or balm', 'A 100mg edible', 'A pre-roll', 'B', 'Topicals provide localized relief without psychoactive effects. Perfect for muscle soreness, joint pain, or skin conditions.', 'cannabis', 'Medium'),
('A first-time customer is nervous about trying cannabis. What''s the best approach?', 'Recommend the strongest product for best value', 'Start with a low-dose product (2.5-5mg edible or a 1:1 product) and educate them', 'Tell them not to worry about dosing', 'Suggest they just try a dab', 'B', 'Low and slow. Start with 2.5-5mg, explain onset times, and make them feel comfortable. A positive first experience creates a loyal customer.', 'cannabis', 'Medium'),
('What is a "session" product?', 'A low-potency product designed for extended, mellow use', 'A product for group use only', 'A limited-edition release', 'An infused pre-roll', 'A', 'Session products are lower in potency, allowing for more relaxed, extended use without getting too impaired. Good for social settings.', 'cannabis', 'Medium'),
('What is the difference between "cured resin" and "live resin"?', 'They are identical', 'Cured resin uses dried flower; live resin uses fresh-frozen flower', 'Live resin has no terpenes', 'Cured resin is always stronger', 'B', 'The key difference is starting material: cured resin uses dried/cured flower; live resin uses plant material frozen immediately after harvest to preserve the full terpene profile.', 'cannabis', 'Medium'),
('Which terpene is also found in black pepper and may help reduce anxiety?', 'Myrcene', 'Limonene', 'Beta-Caryophyllene', 'Pinene', 'C', 'Beta-caryophyllene is found in black pepper, cloves, and cinnamon. Fun tip: chewing black peppercorns may help calm THC-induced anxiety thanks to this terpene.', 'cannabis', 'Medium'),
('What is "flower" in cannabis terms?', 'The dried, smokable buds of the female cannabis plant', 'Any cannabis plant', 'A type of extract', 'The seeds', 'A', 'Flower refers to the dried, trimmed buds of the female cannabis plant — the part with the most cannabinoids and terpenes.', 'cannabis', 'Medium'),
('What is microdosing?', 'Taking extremely small amounts of cannabis (1-5mg THC) for subtle effects', 'Taking the maximum legal dose', 'Only using CBD', 'Smoking very quickly', 'A', 'Microdosing involves consuming very low doses (typically 1-5mg THC) to achieve subtle benefits without significant impairment.', 'cannabis', 'Medium'),
('What is the purpose of a humidity pack (like Boveda) in cannabis storage?', 'To add flavor', 'To maintain optimal humidity (58-65%) and preserve freshness', 'To increase potency', 'To make it smell better', 'B', 'Humidity packs regulate moisture levels in stored cannabis, preventing it from drying out or getting too moist.', 'cannabis', 'Medium'),
('Why is glass preferred over plastic for cannabis storage?', 'Glass is cheaper', 'Glass is airtight, non-reactive, and doesn''t leach chemicals or create static', 'Glass makes cannabis stronger', 'There is no difference', 'B', 'Plastic bags create static that pulls trichomes off the flower, and can leach chemicals over time. Glass is inert and airtight.', 'cannabis', 'Medium'),
('What is the "first-pass effect" and why does it matter for edibles?', 'The first time you try cannabis', 'When THC is metabolized by the liver into a more potent compound (11-hydroxy-THC)', 'The first harvest of the season', 'How quickly you feel effects', 'B', 'The liver converts THC into 11-hydroxy-THC, which crosses the blood-brain barrier more effectively. This is why edibles can feel stronger than smoking.', 'cannabis', 'Medium'),
('What does "craft cannabis" typically refer to?', 'Mass-produced cannabis', 'Small-batch, artisanally grown cannabis with attention to quality over quantity', 'Cannabis used for crafting', 'Any cannabis sold at a dispensary', 'B', 'Craft cannabis is grown in small batches with careful attention to genetics, growing conditions, and curing — similar to craft beer vs. mass-market beer.', 'cannabis', 'Medium'),
('A customer says edibles "don''t work" for them. What might you suggest?', 'They should take a much larger dose', 'Some people metabolize edibles differently; suggest trying a nano-emulsion product or sublingual tincture', 'They should stop trying cannabis', 'Tell them edibles work for everyone the same way', 'B', 'Some people lack certain liver enzymes needed to process edibles efficiently. Nano-emulsion edibles or sublingual tinctures bypass the liver issue.', 'cannabis', 'Medium'),
('What is THCV?', 'A synthetic cannabinoid', 'A minor cannabinoid sometimes called "diet weed" for its appetite-suppressing and energizing properties', 'The same as THC', 'A terpene found in sativa strains', 'B', 'THCV (tetrahydrocannabivarin) may suppress appetite and provide energizing, clear-headed effects. Found in some African sativa strains.', 'cannabis', 'Medium'),
('What is "sugar" as a concentrate consistency?', 'An edible made with sugar', 'A granular, crystalline concentrate with a texture like wet sugar', 'A strain with sweet flavor', 'A way to test potency', 'B', 'Sugar is a concentrate consistency that looks like wet, granular sugar crystals. It''s flavorful and easy to work with.', 'cannabis', 'Medium'),
('How should you help a customer choose between flower and concentrates?', 'Always recommend the most expensive option', 'Ask about their experience level, desired potency, and consumption preferences', 'Only recommend flower', 'Tell them concentrates are better', 'B', 'Understanding the customer''s experience, tolerance, and preferences helps guide them to the right product type.', 'cannabis', 'Medium'),
('What is a "terp sauce"?', 'A cooking sauce with cannabis', 'A high-terpene extract known for rich flavor and aroma', 'A cleaning product for rigs', 'A type of fertilizer', 'B', 'Terp sauce is a high-terpene full-spectrum extract (HTFSE) prized for its rich flavor profile.', 'cannabis', 'Medium'),
('Why might a customer prefer a disposable vape over a cartridge?', 'Disposables are stronger', 'No separate battery needed — everything is in one unit, convenient for occasional use', 'Disposables last longer', 'There is no difference', 'B', 'Disposables are all-in-one (battery + oil). Great for occasional users or travelers who don''t want to invest in a separate battery.', 'cannabis', 'Medium'),
('What does "broad spectrum" mean?', 'Contains all cannabinoids and terpenes including THC', 'Contains multiple cannabinoids and terpenes but with THC removed', 'Contains only CBD', 'A marketing term with no standard meaning', 'B', 'Broad spectrum retains multiple plant compounds but has THC specifically removed. It''s between full-spectrum and isolate.', 'cannabis', 'Medium'),
('What is the ideal temperature range for storing cannabis flower?', '32-50°F', '60-70°F', '80-90°F', 'Temperature doesn''t matter', 'B', '60-70°F (room temperature) is ideal. Too cold can damage trichomes, too warm accelerates cannabinoid degradation.', 'cannabis', 'Medium'),
('What is a "phenotype" in cannabis?', 'A marketing category', 'The physical expression of a plant''s genetics, including appearance, aroma, and effects', 'A type of concentrate', 'A growing technique', 'B', 'Two plants from the same strain can express different phenotypes — different colors, aromas, or growth patterns based on how genetics interact with environment.', 'cannabis', 'Medium');
INSERT INTO trivia_questions (question, option_a, option_b, option_c, option_d, correct_answer, explanation, category, difficulty) VALUES
('What enzyme in the liver is primarily responsible for metabolizing THC?', 'CYP1A2', 'CYP2C9', 'CYP3A4', 'CYP2D6', 'C', 'CYP3A4 is the primary enzyme, with CYP2C9 also playing a role. This is why certain medications that affect these enzymes can interact with cannabis.', 'cannabis', 'Hard'),
('What is the approximate boiling point of THC?', '100°C (212°F)', '157°C (315°F)', '220°C (428°F)', '315°C (600°F)', 'B', 'THC vaporizes at approximately 157°C (315°F). This is why vaporizers typically operate in the 315-410°F range.', 'cannabis', 'Hard'),
('What is winterization in cannabis processing?', 'Growing cannabis in winter conditions', 'Dissolving extract in ethanol and freezing to remove fats, waxes, and lipids', 'Storing flower in cold temperatures', 'A curing technique using cold air', 'B', 'Winterization removes unwanted fats, waxes, and lipids from crude extract by dissolving in ethanol, freezing, and filtering.', 'cannabis', 'Hard'),
('What is the conversion factor for calculating total THC from THCa?', '0.777', '0.877', '0.977', '1.0', 'B', 'Total THC = (THCa x 0.877) + Delta-9 THC. The 0.877 accounts for the molecular weight lost when the carboxyl group is removed during decarboxylation.', 'cannabis', 'Hard'),
('Which federal scheduling category does cannabis currently fall under?', 'Schedule I', 'Schedule II', 'Schedule III', 'It''s been descheduled', 'C', 'Cannabis was rescheduled from Schedule I to Schedule III in 2024, a historic shift acknowledging its medical value.', 'cannabis', 'Hard'),
('What is CRC in concentrate production?', 'Color Remediation Chromatography — using filter media to remove color and impurities', 'Cannabis Research Center', 'Concentrated Resin Compound', 'Certified Retail Cannabis', 'A', 'CRC uses filter media (like activated charcoal and silica) to remove dark pigments and impurities from extracts, producing a lighter-colored product.', 'cannabis', 'Hard'),
('A customer on SSRIs asks about cannabis. What should you be aware of?', 'There are no interactions', 'Cannabis, particularly CBD, can interact with SSRIs via CYP450 enzymes', 'You should adjust their SSRI dose', 'Cannabis replaces the need for SSRIs', 'B', 'CBD inhibits CYP450 enzymes that metabolize many medications including SSRIs. Always advise customers on medications to consult their doctor.', 'cannabis', 'Hard'),
('What is the primary difference between Type I, Type II, and Type III cannabis?', 'They refer to growing methods', 'Type I is THC-dominant, Type II is balanced THC:CBD, Type III is CBD-dominant', 'They refer to concentrate consistencies', 'They refer to packaging sizes', 'B', 'The chemotype classification: Type I = high THC/low CBD, Type II = balanced THC:CBD, Type III = high CBD/low THC. More scientifically useful than indica/sativa.', 'cannabis', 'Hard'),
('What temperature range is considered "low temp" dabbing?', '300-400°F', '400-500°F', '500-600°F', '600-700°F', 'A', 'Low-temp dabs (300-400°F) preserve terpenes and produce smoother, more flavorful hits. Higher temps produce bigger clouds but sacrifice flavor.', 'cannabis', 'Hard'),
('What is a "closed-loop" extraction system?', 'A system where the solvent is contained and recycled, never exposed to air', 'A loop-shaped extraction device', 'A system that runs continuously', 'A type of press', 'A', 'Closed-loop systems contain the solvent within a sealed system, making the process safer and more efficient by recapturing and recycling the solvent.', 'cannabis', 'Hard'),
('Why might two products with the same THC percentage feel different?', 'They shouldn''t feel different', 'Because the terpene profile, minor cannabinoids, and extraction method all influence the experience', 'Because THC percentages are inaccurate', 'Because of the brand name', 'B', 'THC percentage alone doesn''t determine the experience. Terpene profiles, minor cannabinoids (CBN, CBG, THCV), and how the product was made all contribute.', 'cannabis', 'Hard'),
('What is remediation in the context of cannabis testing?', 'Retesting a sample', 'The process of removing contaminants (like mold or pesticides) from failed product', 'A quality grading system', 'A marketing strategy', 'B', 'When cannabis fails lab testing, remediation involves reprocessing to remove the contaminants so it can pass retesting.', 'cannabis', 'Hard'),
('What is a "hot" cannabis product in regulatory terms?', 'A bestselling product', 'A product that exceeds the legal THC limit for its category', 'A product that''s been heated', 'A product with high demand', 'B', 'A "hot" product has tested above the legal THC threshold, which could cause compliance issues.', 'cannabis', 'Hard'),
('What is the significance of the "headspace" in a vape cartridge?', 'It''s where the vapor collects', 'The air bubble at the top is normal — oil is absorbed by the wick and coil during filling', 'It indicates a defective product', 'It means the cart is half empty', 'B', 'The headspace bubble is normal. Oil gets absorbed by the ceramic or cotton wick during manufacturing. It doesn''t mean product is missing.', 'cannabis', 'Hard'),
('How does altitude affect cannabis cultivation?', 'It has no effect', 'Higher altitude means more UV exposure, which can increase trichome production', 'Higher altitude reduces THC', 'Cannabis can''t grow above 1000 feet', 'B', 'At higher altitudes, plants receive more UV radiation. Some cultivators believe this stresses the plant into producing more trichomes as a protective mechanism.', 'cannabis', 'Hard'),
('What is the "wash" in ice water hash production?', 'Cleaning the equipment', 'The process of agitating cannabis in ice water to separate trichomes, then filtering through mesh bags', 'Rinsing the final product', 'A quality inspection step', 'B', 'The wash involves agitating cannabis material in ice water, which makes trichomes brittle and break off. They''re then collected through progressively finer mesh bags.', 'cannabis', 'Hard'),
('What is "rosin tech"?', 'A proprietary growing method', 'Using heat and pressure to squeeze resinous oil from flower or hash without solvents', 'A type of genetic engineering', 'A curing technique', 'B', 'Rosin tech uses a heated press to squeeze cannabis, producing a solventless concentrate. It can even be done at home with a hair straightener (though a proper press is better).', 'cannabis', 'Hard'),
('What is "jar tech" or "jar cure" for concentrates?', 'Storing concentrates in the refrigerator', 'Sealing concentrate in a jar at warm temperature to change consistency and nucleate crystals', 'Using mason jars for extraction', 'A labeling technique', 'B', 'Jar tech involves sealing concentrate in a jar at 90-100°F, allowing THCa to crystallize (diamond formation) while terpenes separate into a liquid sauce.', 'cannabis', 'Hard'),
('What does "mechanical separation" mean in concentrate production?', 'Using machines to trim plants', 'Physically separating trichomes from plant material without chemical solvents (dry sift, ice water hash)', 'Grinding flower in a blender', 'An automated packaging process', 'B', 'Mechanical separation uses physical methods like sifting through mesh screens (dry sift) or ice water agitation (bubble hash) to collect trichomes.', 'cannabis', 'Hard'),
('A customer asks why live rosin is more expensive than cured BHO shatter. How do you explain it?', 'Live rosin is always better', 'Live rosin uses fresh-frozen input and a solventless process, requiring more starting material and labor than solvent-based extraction', 'Shatter is old technology', 'It''s just marketing', 'B', 'Live rosin requires more cannabis per gram of output and more labor-intensive processes. The solventless method and fresh-frozen starting material add to costs.', 'cannabis', 'Hard'),
('What is the difference between "headstash" and regular product?', 'Headstash is for managers only', 'Headstash typically refers to the grower''s personal favorite, top-quality reserve batch', 'Headstash is a strain name', 'There is no difference', 'B', 'Headstash is slang for a cultivator''s personal reserve — their best flower set aside. Some brands use it to market their premium tier.', 'cannabis', 'Hard'),
('What is the "entourage effect" specifically attributed to, scientifically?', 'Marketing by cannabis companies', 'The synergistic interaction between cannabinoids, terpenes, and flavonoids enhancing therapeutic outcomes', 'The social experience of using cannabis with friends', 'THC potency alone', 'B', 'Proposed by Dr. Raphael Mechoulam, the entourage effect suggests the full spectrum of compounds work together synergistically, producing effects beyond what any single compound achieves alone.', 'cannabis', 'Hard'),
